import sys
MOD = 998244353

def solve(n, points):
    a = [0] * (n + 2)
    a[0] = n + 1
    for x, y in points:
        a[x] = y
    dp = [0] * (n + 2)
    dp[0] = 1
    for r in range(1, n + 2):
        low = a[r]
        total = 0
        for l in range(r):
            high = a[l]
            if high <= low or dp[l] == 0:
                continue
            vals = [a[t] for t in range(l + 1, r) if low < a[t] < high]
            mins = []
            mn = n + 1
            for y in vals:
                mins.append(mn)
                if y < mn:
                    mn = y
            mx = 0
            valid = True
            for t in range(len(vals) - 1, -1, -1):
                y = vals[t]
                if mins[t] > y > mx:
                    valid = False
                    break
                if y > mx:
                    mx = y
            if valid:
                total += dp[l]
        dp[r] = total % MOD
    return dp[n + 1]

