import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]

    # bounds[l][k]: smallest right endpoint of a condition at k
    # whose left endpoint is at least l (positions are zero-based).
    # Right endpoints retain their one-based input value.
    bounds = [[n + 1] * n for _ in range(n + 1)]
    for j in range(2, len(data), 3):
        l, r, x = data[j:j + 3]
        if r < bounds[l - 1][x - 1]:
            bounds[l - 1][x - 1] = r
    for l in range(n - 2, -1, -1):
        a, b = bounds[l], bounds[l + 1]
        for k in range(n):
            if b[k] < a[k]:
                a[k] = b[k]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the number of valid relative orders on [l,r),
    # divided by (r-l)!. Keep its transpose for fast inner loops.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    tr = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = tr[i][i] = 1

    for l in range(n - 1, -1, -1):
        row = dp[l]
        lim = bounds[l]
        for r in range(l + 1, n + 1):
            col = tr[r]
            total = 0
            for k in range(l, r):
                if r < lim[k]:
                    total += row[k] * col[k + 1]
            value = (total % MOD) * inv[r - l] % MOD
            row[r] = col[l] = value

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)


if __name__ == '__main__':
    solve()

