import sys
from collections import deque
from array import array


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    a = [next(it) - 1 for _ in range(n)]
    mod = 998244353
    deg = [0] * n
    for v in a:
        deg[v] += 1
    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n

    while q:
        v = q.popleft()
        p = a[v]
        src = dp[v]
        dst = dp[p]
        dp[v] = None
        if src is None:
            if dst is None:
                dp[p] = array('I', range(1, m + 1))
            else:
                for j in range(m):
                    dst[j] = dst[j] * (j + 1) % mod
        else:
            s = 0
            if dst is None:
                for j in range(m):
                    s = (s + src[j]) % mod
                    src[j] = s
                dp[p] = src
            else:
                for j in range(m):
                    s = (s + src[j]) % mod
                    dst[j] = dst[j] * s % mod
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    ans = 1
    for start in range(n):
        if deg[start] == 0:
            continue
        cur = start
        prod = None
        while deg[cur]:
            deg[cur] = 0
            row = dp[cur]
            if row is not None:
                if prod is None:
                    prod = row
                else:
                    for j in range(m):
                        prod[j] = prod[j] * row[j] % mod
            cur = a[cur]
        ways = m if prod is None else sum(prod) % mod
        ans = ans * ways % mod
    print(ans)


if __name__ == '__main__':
    solve()

