import sys

MOD = 998244353


def solve(data):
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                factors.setdefault(p, []).append((i, e))
            p += 1
        if x > 1:
            factors.setdefault(x, []).append((i, 1))

    answer = 1
    for p, events in factors.items():
        total = sum(e for _, e in events)
        weights = {}
        # Last exponent after normalizing the minimum prefix exponent to zero.
        dp = [1]
        for j, (i, e) in enumerate(events):
            end = events[j + 1][0] if j + 1 < len(events) else n - 1
            gap = end - i
            if gap not in weights:
                base = pow(p, gap, MOD)
                w = [1] * (total + 1)
                for h in range(1, total + 1):
                    w[h] = w[h - 1] * base % MOD
                weights[gap] = w
            w = weights[gap]
            ndp = [0] * (len(dp) + e)
            shift = pow(p, i + 1, MOD)
            shifts = [1] * (e + 1)
            for k in range(1, e + 1):
                shifts[k] = shifts[k - 1] * shift % MOD

            for h, v in enumerate(dp):
                if v:
                    ndp[h + e] = v
                    if h >= e:
                        ndp[h - e] += v
                    else:
                        # A new minimum raises all previous exponents.
                        ndp[0] += v * shifts[e - h] % MOD
            dp = [v * w[h] % MOD for h, v in enumerate(ndp)]
        answer = answer * (sum(dp) % MOD) % MOD
    return answer


if __name__ == '__main__':
    print(solve(list(map(int, sys.stdin.buffer.read().split()))))

