from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, i))

        gains = [0] * len(conflictingPairs)
        largest = second = 0
        owner = 0
        total = 0

        for right in range(1, n + 1):
            for a, i in ending[right]:
                if a > largest:
                    second = largest
                    largest = a
                    owner = i
                elif a > second:
                    second = a

            # Valid starts must be strictly greater than largest.
            total += right - largest
            # Only removing the largest constraint can help at this endpoint.
            gains[owner] += largest - second

        return total + max(gains)

