        for i in indices:
            di = d[i]
            v = di[k]
            if v == INF:
                continue
            for j in indices:
                z = v + dk[j]
                if z < di[j]:
                    di[j] = z

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
