import sys
from functools import lru_cache


def solve(A, B, M):
    # Count insertion tableaux satisfying the additional diagonal relations.
    if A <= B:
        vals = [B] * (A - 1) + [B - 1]
        dim, lim, columns = A, B, True
    else:
        vals = [A] * (B - 1) + [A - 1]
        dim, lim, columns = B, A, False

    bits = lim.bit_length()
    mask = (1 << bits) - 1
    steps = [1 << (bits * i) for i in range(dim)]
    start = sum(x * s for x, s in zip(vals, steps))

    @lru_cache(None)
    def dp(state):
        if state == 0:
            return 1
        v = [(state >> (bits * i)) & mask for i in range(dim)]
        ans = 0
        for i in range(dim):
            h = v[i]
            if not h or (i + 1 < dim and h <= v[i + 1]):
                continue
            if columns:
                if i == dim - 2 and v[-1] > 0 and h - 1 <= v[-1]:
                    continue
            else:
                if h == A - 1 and i and v[i - 1] == A:
                    continue
            ans += dp(state - steps[i])
        return ans % M

    good = dp(start)

    # The recording tableau is arbitrary: use the hook-length formula.
    factorial = 1
    for i in range(1, A * B):
        factorial = factorial * i % M
    hooks = 1
    for r in range(B):
        width = A - (r == B - 1)
        for c in range(width):
            height = B - (c == A - 1)
            hooks = hooks * (width - c + height - r - 1) % M
    return good * factorial * pow(hooks, M - 2, M) % M


if __name__ == '__main__':
    print(solve(*map(int, sys.stdin.buffer.read().split())))

