import sys
from math import gcd


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[:2]
    rows = []
    upper = 10**9
    for i in range(n):
        a, p, b, q = data[2 + 4*i:6 + 4*i]
        upper = min(upper, max(x*a//p, x*b//q))
        # S has at least as good a capacity-to-cost ratio as T.
        if a*q < b*p:
            a, p, b, q = b, q, a, p
        limit = a // gcd(a, b)
        rows.append((a, p, b, q, limit))

    def feasible(w):
        total = 0
        for a, p, b, q, limit in rows:
            best = ((w + a - 1) // a) * p
            # Any 'limit' T machines can be replaced by S machines
            # with equal capacity and no greater cost.
            for t in range(1, min(limit, (w + b - 1)//b + 1)):
                rem = w - t*b
                cost = t*q + max(0, (rem + a - 1)//a)*p
                if cost < best:
                    best = cost
            total += best
            if total > x:
                return False
        return True

    lo, hi = 0, upper + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)


if __name__ == '__main__':
    solve()

