class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        # After the first operation, only the number of set bits matters.
        depth = [0] * (length + 1)
        for i in range(2, length + 1):
            depth[i] = 1 + depth[i.bit_count()]
        good = [i for i in range(1, length + 1) if depth[i] < k]

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % mod
        inv = [1] * (length + 1)
        inv[length] = pow(fact[length], mod - 2, mod)
        for i in range(length, 0, -1):
            inv[i - 1] = inv[i] * i % mod

        answer = 0
        prefix = 0
        for pos, bit in enumerate(s):
            if bit == '1':
                # Choose zero here to make the number strictly smaller.
                remaining = length - pos - 1
                total = 0
                for count in good:
                    need = count - prefix
                    if need < 0:
                        continue
                    if need > remaining:
                        break
                    total += inv[need] * inv[remaining - need]
                answer = (answer + fact[remaining] * (total % mod)) % mod
                prefix += 1
        return answer

