import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for i in range(m):
        u, v = data[2 + 2 * i] - 1, data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivots = []
    rank = 0
    for col in range(n):
        bit = 1 << col
        p = next((i for i in range(rank, n) if rows[i] & bit), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        for i in range(n):
            if i != rank and rows[i] & bit:
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [i for i in range(n) if i not in pivot_set]
    ans = [0] * n
    for k, col in enumerate(free):
        ans[col] = 1 << k
    for i, col in enumerate(pivots):
        for f in free:
            if rows[i] & (1 << f):
                ans[col] ^= ans[f]

    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)


