from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        ans = 0
        for dr, dc in ((1, 1), (1, -1), (-1, -1), (-1, 1)):
            # A clockwise turn transforms (dr, dc) into (dc, -dr).
            er, ec = dc, -dr
            suffix = [[0] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if er == 1 else range(n)
            cols = range(m - 1, -1, -1) if ec == 1 else range(m)
            for r in rows:
                for c in cols:
                    nr, nc = r + er, c + ec
                    value = grid[r][c]
                    expected = 2 if value == 1 else 2 - value
                    length = 1
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == expected:
                        length += suffix[nr][nc]
                    suffix[r][c] = length

            # Prefixes must start with 1 and follow the initial direction.
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            cols = range(m) if dc == 1 else range(m - 1, -1, -1)
            prev = [0] * m
            for r in rows:
                curr = [0] * m
                for c in cols:
                    value = grid[r][c]
                    length = 0
                    if value == 1:
                        length = 1
                    else:
                        pr, pc = r - dr, c - dc
                        if 0 <= pr < n and 0 <= pc < m and prev[pc]:
                            pv = grid[pr][pc]
                            if value == (2 if pv == 1 else 2 - pv):
                                length = prev[pc] + 1
                    curr[c] = length
                    if length:
                        ans = max(ans, length + suffix[r][c] - 1)
                prev = curr
        return ans

