from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odds, evens = (n + 1) // 2, n // 2
        total = fact[odds] * fact[evens] * (2 if n % 2 == 0 else 1)
        if k > total:
            return []

        remaining = list(range(1, n + 1))
        answer = []
        parity = 1 if n % 2 else None
        while remaining:
            for i, x in enumerate(remaining):
                p = x % 2
                if parity is not None and p != parity:
                    continue
                o = odds - p
                e = evens - (1 - p)
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(x)
                    remaining.pop(i)
                    odds, evens = o, e
                    parity = 1 - p
                    break
        return answer

