from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        weights = [0] * m
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            j = n - 1 - i
            weights[i] = ((powers[i] + powers[j]) % k
                          if i != j else powers[i])
            # Remaining digits can realize exactly the multiples of this gcd.
            suffix[i] = gcd(suffix[i + 1], weights[i])

        answer = ['0'] * n
        remainder = 0
        for i in range(m):
            w = weights[i]
            g = suffix[i + 1]
            for d in range(9, -1 if i else 0, -1):
                if (remainder + d * w) % g == 0:
                    answer[i] = answer[n - 1 - i] = str(d)
                    remainder = (remainder + d * w) % k
                    break
        return ''.join(answer)

