class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        q = deque()
        right = len(nums) - 1
        cost = ans = 0
        for left in range(len(nums) - 1, -1, -1):
            value = nums[left]
            while q and nums[q[0]] < value:
                j = q.popleft()
                end = q[0] if q else right + 1
                cost += (end - j) * (value - nums[j])
            q.appendleft(left)
            while cost > k:
                cost -= nums[q[-1]] - nums[right]
                if q[-1] == right:
                    q.pop()
                right -= 1
            ans += right - left + 1
        return ans
