def prefixes(a):
    low = []
    high = []
    sl = sh = 0
    result = [0]
    push = heapq.heappush
    pop = heapq.heappop
    for i, x in enumerate(a):
        if not low or x <= -low[0]:
            push(low, -x)
            sl += x
        else:
            push(high, x)
            sh += x
        if len(low) > len(high) + 1:
            v = -pop(low)
            sl -= v
            sh += v
            push(high, v)
        elif len(high) > len(low):
            v = pop(high)
            sh -= v
            sl += v
            push(low, -v)
        if i & 1:
            result.append(sh - sl)
    return result

def candidate(a):
    n=len(a)
