import sys

MOD = 998244353


def count(h, w, rows):
    if any(s.count(b'A') & 1 for s in rows):
        return 0

    n = h + w
    parent = [-1] * n
    parity = bytearray(n)
    col = bytearray(w)
    components = n

    def find(x):
        v = 0
        while parent[x] >= 0:
            p = parent[x]
            if parent[p] >= 0:
                parity[x] ^= parity[p]
                parent[x] = parent[p]
            v ^= parity[x]
            x = parent[x]
        return x, v

    for i, s in enumerate(rows):
        row = 0
        for j, c in enumerate(s):
            if c == 65:
                row ^= 1
                col[j] ^= 1
            else:
                a, pa = find(i)
                b, pb = find(h + j)
                v = 1 ^ row ^ col[j] ^ pa ^ pb
                if a == b:
                    if v:
                        return 0
                else:
                    if parent[a] > parent[b]:
                        a, b = b, a
                    parent[a] += parent[b]
                    parent[b] = a
                    parity[b] = v
                    components -= 1

    if any(col):
        return 0
    return pow(2, components, MOD)


def main():
    f = sys.stdin.buffer
    t = int(f.readline())
    out = []
    for _ in range(t):
        h, w = map(int, f.readline().split())
        rows = [f.readline().strip() for _ in range(h)]
        out.append(str(count(h, w, rows)))
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    main()

