class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def occurrences(t):
            m = len(t)
            if m == 0:
                return range(len(s) + 1)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        a, b, c = p.split('*')
        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        j = k = 0
        ans = len(s) + 1
        la, lb, lc = len(a), len(b), len(c)
        for start in aa:
            while j < len(bb) and bb[j] < start + la:
                j += 1
            if j == len(bb):
                break
            while k < len(cc) and cc[k] < bb[j] + lb:
                k += 1
            if k == len(cc):
                break
            ans = min(ans, cc[k] + lc - start)
        return ans if ans <= len(s) else -1

