import sys


def solve(n, a, b):
    if a == b:
        return 0
    p = [i + 1 for i, c in enumerate(a) if c == 49]
    q = [i + 1 for i, c in enumerate(b) if c == 49]
    m = len(p)
    h = len(q)
    if h > m:
        return -1

    zeros = [q[i + 1] - q[i] - 1 for i in range(h - 1)]
    zeros.append(n - q[-1])
    answer = 4 * n + 1

    for parity in range(2):
        x = q[0] - 1 - 2 * n - parity
        j = 0
        for t, z in enumerate(zeros):
            if j == m:
                break
            end = p[j] if t < h - 1 else p[-1]
            end += (end - x - 1) & 1
            while True:
                while j < m and p[j] <= end:
                    j += 1
                if j == m or p[j] > end + z:
                    break
                end = p[j]
                end += (end - x - 1) & 1
            x = end + z
        else:
            if j == m:
                k = max(0, q[0] - p[0], x - n)
                k += (k - parity) & 1
                answer = min(answer, k)

    return answer if answer <= 2 * n + 1 else -1


def main():
    f = sys.stdin.buffer
    out = []
    for _ in range(int(f.readline())):
        n = int(f.readline())
        a = f.readline().strip()
        b = f.readline().strip()
        out.append(str(solve(n, a, b)))
    sys.stdout.write('\n'.join(out))


