import sys
import heapq


def solve(N, W, items):
    groups = [[] for _ in range(W + 1)]
    for w, v in items:
        groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        h = groups[w]
        if not h:
            continue
        heapq.heapify(h)
        pre = [0]
        for _ in range(W // w):
            x = h[0]
            if x >= 0:
                break
            pre.append(pre[-1] - x)
            heapq.heapreplace(h, x + 2)

        m = len(pre) - 1
        if m == 0:
            continue

        if m <= 8:
            for k in range(1, m + 1):
                v = pre[k] - pre[k - 1]
                for j in range(W, w - 1, -1):
                    z = dp[j - w] + v
                    if z > dp[j]:
                        dp[j] = z
            continue

        # The concave prefix values give monotone optimal split points.
        def calc(lo, hi, ol, oh):
            if lo > hi:
                return
            mid = (lo + hi) // 2
            start = max(ol, mid - m)
            end = min(mid, oh)
            best = -1
            opt = start
            for j in range(start, end + 1):
                z = old[j] + pre[mid - j]
                if z > best:
                    best = z
                    opt = j
            new[mid] = best
            calc(lo, mid - 1, ol, opt)
            calc(mid + 1, hi, opt, oh)

        for r in range(w):
            old = dp[r::w]
            new = [0] * len(old)
            new[0] = old[0]
            calc(1, len(old) - 1, 0, len(old) - 1)
            dp[r::w] = new

    return dp[W]


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, W = data[:2]
    items = list(zip(data[2::2], data[3::2]))
    print(solve(N, W, items))


if __name__ == '__main__':
    main()

