from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Each subtree occupies one contiguous interval in postorder.
        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            if x >= 0:
                start[x] = len(order)
                stack.append(~x)
                stack.extend(reversed(children[x]))
            else:
                x = ~x
                order.append(s[x])
                end[x] = len(order)

        # Manacher's algorithm handles odd and even lengths together.
        t = '^#' + '#'.join(order) + '#$'
        radius = [0] * len(t)
        center = right = 0
        for i in range(1, len(t) - 1):
            if i < right:
                radius[i] = min(right - i, radius[2 * center - i])
            r = radius[i]
            while t[i - r - 1] == t[i + r + 1]:
                r += 1
            radius[i] = r
            if i + r > right:
                center, right = i, i + r

        return [
            radius[start[i] + end[i] + 1] >= end[i] - start[i]
            for i in range(n)
        ]

