class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        # dp[k] is the length obtained from 'a' after k steps.
        dp = [1] * (t + 26)
        for k in range(26, t + 26):
            dp[k] = (dp[k - 26] + dp[k - 25]) % mod
        return sum(dp[t + ord(c) - 97] for c in s) % mod

