class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        l = r = 0
        for k in range(1, n):
            v = 0
            if k < r:
                v = z[k - l]
                if v > r - k:
                    v = r - k
            while k + v < n and nums[v] == nums[k + v]:
                v += 1
            z[k] = v
            if k + v > r:
                l, r = k, k + v

        ans = 0
        for i in range(1, n - 1):
            limit = (n - i) // 2
            if z[i] >= i:
                if n > 2 * i:
                    ans += n - 2 * i
                if limit >= i:
                    limit = i - 1
            if not limit:
                continue
            end = limit * 2
            a = nums[i:i + end]
            zz = [0] * (limit + 1)
            l = r = 0
            for k in range(1, limit + 1):
                v = 0
                if k < r:
                    v = zz[k - l]
                    if v > r - k:
                        v = r - k
                while k + v < end and a[v] == a[k + v]:
