import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # A reversed spanning tree gives at most one outgoing edge per
        # original vertex, so every allowed threshold is sufficient.
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        dist = [1000001] * n
        dist[0] = 0
        heap = [(0, 0)]
        remaining = n

        while heap:
            cost, node = heapq.heappop(heap)
            if cost != dist[node]:
                continue
            remaining -= 1
            if remaining == 0:
                return cost

            for nxt, weight in reverse[node]:
                candidate = max(cost, weight)
                if candidate < dist[nxt]:
                    dist[nxt] = candidate
                    heapq.heappush(heap, (candidate, nxt))

        return -1

