def brute(points):
    best = -1
    for corners in combinations(points, 4):
        xs = sorted(set(x for x,y in corners))
        ys = sorted(set(y for x,y in corners))
        if len(xs) != 2 or len(ys) != 2:
            continue
        if any(p not in corners and xs[0] <= p[0] <= xs[1] and ys[0] <= p[1] <= ys[1] for p in points):
            continue
        best = max(best, (xs[1]-xs[0])*(ys[1]-ys[0]))
    return best

